function meshIn(vertices: number, vertexCount: number, triangles: number, triangleCount: number): number {
    if (triangleCount % 3) throw new MathError(-1);
    const p = alloc(16);
    w_RantMeshView(p, { vertices, vertex_count: vertexCount, triangles, triangle_count: triangleCount / 3 });
    return p;
}

function prismIn(prism: Prism): number {
    const count = countOf(prism.base.points, 2);
    const base = listIn(prism.base.points, count, 16, w_RantDouble2);
    const pose = alloc(56);
    w_RantPose(pose, prism.pose);
    const p = alloc(72);
    w_RantPrismView(p, { pose: prism.pose, base: { points: base, count }, height: prism.height });
    return p;
}

function prismOf(p: number): Prism {
    const v = r_RantPrismView(p);
    return { pose: v.pose, base: { points: listOut(v.base.points, v.base.count, 16, r_RantDouble2, 2, false) as Double2[] }, height: v.height };
}

function matrixIn(m: Matrix): number {
    if (lengthOf(m.data) !== m.rows * m.cols) throw new MathError(-1);
    const p = alloc(12);
    w_RantMatrixView(p, { data: numbersIn(m.data, 8, Float64Array), rows: m.rows, cols: m.cols });
    return p;
}

function matrixOut(rows: number, cols: number) {
    const data = alloc(8 * rows * cols);
    const view = alloc(12);
    w_RantMatrixView(view, { data, rows, cols });
    return { view, matrix: (): Matrix => ({ rows, cols, data: numbersOut(data, rows * cols, Float64Array) }) };
}

function imageIn(image: Image): number {
    const data = alloc(image.data.length);
    U8.set(image.data, data);
    const p = alloc(24);
    w_RantImageView(p, { width: image.width, height: image.height, stride: image.stride, format: image.format, data, size: image.data.length });
    return p;
}

function imageDone(image: Image, p: number): void {
    const v = r_RantImageView(p);
    image.data.set(U8.subarray(v.data, v.data + image.data.length));
}

function imageOut(format: ImageFormat, width: number, height: number) {
    const size = wasm._rm_image_bytes(enumIn(ImageFormatValues, format), width, height) >>> 0;
    const data = alloc(size);
    const view = alloc(24);
    w_RantImageView(view, { width, height, stride: 0, format, data, size });
    return { view, image: (): Image => ({ width, height, stride: 0, format, data: U8.slice(data, data + size) }) };
}

function imageCopy(part: number): Image {
    const v = r_RantImageView(part);
    const out = imageOut(v.format, v.width, v.height);
    check(wasm._rm_image_convert(part, out.view));
    refresh();
    return out.image();
}

function fieldsIn(fields: readonly PointField[]): number {
    const p = alloc(20 * fields.length);
    fields.forEach((f, i) => {
        const name = stringIn(f.name);
        w_RantPointFieldView(p + 20 * i, { name, name_len: new TextEncoder().encode(f.name).length, offset: f.offset, kind: f.kind, count: f.count });
    });
    return p;
}

function cloudIn(cloud: PointCloud): number {
    const data = alloc(cloud.data.length);
    U8.set(cloud.data, data);
    const p = alloc(20);
    w_RantPointCloudView(p, { fields: fieldsIn(cloud.fields), field_count: cloud.fields.length, point_step: cloud.point_step, data, size: cloud.data.length });
    return p;
}

function cloudDone(cloud: PointCloud, p: number): void {
    const v = r_RantPointCloudView(p);
    cloud.data.set(U8.subarray(v.data, v.data + cloud.data.length));
}

function fieldOf(p: number): PointField {
    const f = r_RantPointFieldView(p);
    return { name: new TextDecoder().decode(U8.subarray(f.name, f.name + f.name_len)), offset: f.offset, kind: f.kind, count: f.count };
}

function cloudLike(p: number): PointCloud {
    const v = r_RantPointCloudView(p);
    return {
        fields: Array.from({ length: v.field_count }, (_, i) => fieldOf(v.fields + 20 * i)),
        point_step: v.point_step,
        data: new Uint8Array(0),
    };
}

function gridIn(grid: Grid): number {
    const fields = alloc(20 * grid.fields.length);
    grid.fields.forEach((f, i) => {
        const data = alloc(f.data.length);
        U8.set(f.data, data);
        const name = stringIn(f.name);
        w_RantGridFieldView(fields + 20 * i, { name, name_len: new TextEncoder().encode(f.name).length, kind: f.kind, data, size: f.data.length });
    });
    const p = alloc(88);
    w_RantGridView(p, {
        origin: grid.origin.pose, resolution: grid.resolution, cells_x: grid.cells_x, cells_y: grid.cells_y, cells_z: grid.cells_z,
        fields, field_count: grid.fields.length,
    });
    return p;
}

function gridDone(grid: Grid, p: number): void {
    const v = r_RantGridView(p);
    grid.fields.forEach((f, i) => {
        const g = r_RantGridFieldView(v.fields + 20 * i);
        f.data.set(U8.subarray(g.data, g.data + f.data.length));
    });
}

function scanIn(scan: LaserScan): number {
    const p = alloc(48);
    w_RantLaserScanView(p, {
        angle_min: scan.angle_min, angle_step: scan.angle_step, range_min: scan.range_min, range_max: scan.range_max,
        echoes: scan.echoes, ranges: numbersIn(scan.ranges, 4, Float32Array), range_count: lengthOf(scan.ranges),
    });
    return p;
}

function detectionsIn(list: readonly any[], size: number, write: (p: number, v: any) => void, _box: unknown): number {
    const p = alloc(size * list.length);
    list.forEach((d, i) => {
        write(p + size * i, { bounds: d.bounds, label: stringIn(d.label), label_len: new TextEncoder().encode(d.label).length, score: d.score });
    });
    return p;
}

function fitIn(options: FitOptions | null, count: number): number {
    if (!options) return 0;
    if (options.weights && lengthOf(options.weights) !== count) throw new MathError(-1);
    if (options.inliers && options.inliers.length !== count) throw new MathError(-1);
    const p = alloc(40);
    w_RantFitOptions(p, {
        weights: options.weights ? numbersIn(options.weights, 8, Float64Array) : 0,
        tolerance: options.tolerance ?? 0, tries: options.tries ?? 0, seed: options.seed ?? 0,
        inliers: options.inliers ? alloc(count) : 0,
    });
    return p;
}

function fitDone(options: FitOptions | null, p: number): void {
    if (!options?.inliers) return;
    const v = r_RantFitOptions(p);
    options.inliers.set(U8.subarray(v.inliers, v.inliers + options.inliers.length));
}

function alignIn(options: AlignOptions | null, source: number, target: number): number {
    if (!options) return 0;
    const normals = options.normals ?? null;
    if (normals && countOf(normals, 3) !== target) throw new MathError(-1);
    if (options.inliers && options.inliers.length !== source) throw new MathError(-1);
    const p = alloc(32);
    const error = alloc(8);
    F64[error >> 3] = 0;
    w_RantAlignOptions(p, {
        max_distance: options.max_distance ?? 0, iterations: options.iterations ?? 0,
        normals: normals ? listIn(normals, target, 24, w_RantDouble3) : 0,
        inliers: options.inliers ? alloc(source) : 0,
        error,
    });
    return p;
}

function alignDone(options: AlignOptions | null, p: number): void {
    if (!options) return;
    const v = r_RantAlignOptions(p);
    if (options.inliers) options.inliers.set(U8.subarray(v.inliers, v.inliers + options.inliers.length));
    options.error = F64[v.error >> 3];
}

/** A kd tree over a copy of some points. Call free when done, or leave it to the collector. */
export class KdTree {
    private raw: number;
    private static registry = new FinalizationRegistry((raw: number) => wasm._rm_kdtree_destroy(raw));
    constructor(raw: number) {
        this.raw = raw;
        KdTree.registry.register(this, raw, this);
    }
    handle(): number {
        if (!this.raw) throw new MathError(-1);
        return this.raw;
    }
    free(): void {
        if (!this.raw) return;
        KdTree.registry.unregister(this);
        wasm._rm_kdtree_destroy(this.raw);
        this.raw = 0;
    }
    [Symbol.dispose](): void {
        this.free();
    }
}

function shapeIn(shape: Shape): number {
    const ret = alloc(88);
    const v = shape.value;
    switch (shape.kind) {
    case "aligned_box": { const c = alloc(48); w_RantAlignedBox(c, v); wasm._rm_shape_from_aligned_box(ret, c); break; }
    case "oriented_box": { const c = alloc(80); w_RantOrientedBox(c, v); wasm._rm_shape_from_oriented_box(ret, c); break; }
    case "sphere": { const c = alloc(32); w_RantSphere(c, v); wasm._rm_shape_from_sphere(ret, c); break; }
    case "capsule": { const c = alloc(56); w_RantCapsule(c, v); wasm._rm_shape_from_capsule(ret, c); break; }
    case "cylinder": { const c = alloc(56); w_RantCylinder(c, v); wasm._rm_shape_from_cylinder(ret, c); break; }
    case "cone": { const c = alloc(56); w_RantCone(c, v); wasm._rm_shape_from_cone(ret, c); break; }
    case "segment": { const c = alloc(48); w_RantSegment(c, v); wasm._rm_shape_from_segment(ret, c); break; }
    case "prism": {
        const c = alloc(72);
        w_RantPrismView(c, { pose: v.pose, base: { points: numbersIn(v.base, 8, Float64Array), count: v.base.length / 2 }, height: v.height });
        wasm._rm_shape_from_prism(ret, c);
        break;
    }
    case "polyline": wasm._rm_shape_from_polyline(ret, viewIn(numbersIn(v, 8, Float64Array), v.length / 3)); break;
    case "polygon": wasm._rm_shape_from_polygon(ret, viewIn(numbersIn(v, 8, Float64Array), v.length / 3)); break;
    case "mesh":
        wasm._rm_shape_from_mesh(ret, meshIn(numbersIn(v.vertices, 8, Float64Array), v.vertices.length / 3, numbersIn(v.triangles, 4, Uint32Array), v.triangles.length));
        break;
    default: throw new MathError(-1);
    }
    refresh();
    return ret;
}

function shape2dIn(shape: Shape2D): number {
    const ret = alloc(48);
    const v = shape.value;
    switch (shape.kind) {
    case "aligned_box2d": { const c = alloc(32); w_RantAlignedBox2D(c, v); wasm._rm_shape2d_from_aligned_box2d(ret, c); break; }
    case "oriented_box2d": { const c = alloc(40); w_RantOrientedBox2D(c, v); wasm._rm_shape2d_from_oriented_box2d(ret, c); break; }
    case "circle": { const c = alloc(24); w_RantCircle(c, v); wasm._rm_shape2d_from_circle(ret, c); break; }
    case "capsule2d": { const c = alloc(40); w_RantCapsule2D(c, v); wasm._rm_shape2d_from_capsule2d(ret, c); break; }
    case "segment2d": { const c = alloc(32); w_RantSegment2D(c, v); wasm._rm_shape2d_from_segment2d(ret, c); break; }
    case "polygon2d": wasm._rm_shape2d_from_polygon2d(ret, viewIn(numbersIn(v, 8, Float64Array), v.length / 2)); break;
    case "polyline2d": wasm._rm_shape2d_from_polyline2d(ret, viewIn(numbersIn(v, 8, Float64Array), v.length / 2)); break;
    default: throw new MathError(-1);
    }
    refresh();
    return ret;
}

