export function matrixMultiply(a: Matrix, b: Matrix): Matrix {
    begin();
    const c_a = matrixIn(a);
    const c_b = matrixIn(b);
    const o0 = matrixOut(a.rows, b.cols);
    check(wasm._rm_matrix_multiply(c_a, c_b, o0.view));
    refresh();
    return o0.matrix();
}

export function matrixTranspose(a: Matrix): Matrix {
    begin();
    const c_a = matrixIn(a);
    const o0 = matrixOut(a.cols, a.rows);
    check(wasm._rm_matrix_transpose(c_a, o0.view));
    refresh();
    return o0.matrix();
}

export function matrixDeterminant(a: Matrix): number {
    begin();
    const c_a = matrixIn(a);
    const o0 = alloc(8);
    check(wasm._rm_matrix_determinant(c_a, o0));
    refresh();
    return F64[(o0) >> 3];
}

export function matrixInverse(a: Matrix): Matrix {
    begin();
    const c_a = matrixIn(a);
    const o0 = matrixOut(a.rows, a.cols);
    check(wasm._rm_matrix_inverse(c_a, o0.view));
    refresh();
    return o0.matrix();
}

/** x such that a x = b, each column of b solved alone. With more rows than columns, the x with the
 * least squared error. Fails when the columns of a are dependent. */
export function matrixSolve(a: Matrix, b: Matrix): Matrix {
    begin();
    const c_a = matrixIn(a);
    const c_b = matrixIn(b);
    const o0 = matrixOut(a.cols, b.cols);
    check(wasm._rm_matrix_solve(c_a, c_b, o0.view));
    refresh();
    return o0.matrix();
}

/** a = u diag(s) v^T for an m by n matrix and k = min(m, n): u is m by k, s holds k values from the
 * largest down, v is n by k. */
export function matrixSvd(a: Matrix): [Matrix, Float64Array, Matrix] {
    begin();
    const c_a = matrixIn(a);
    const o0 = matrixOut(a.rows, Math.min(a.rows, a.cols));
    const s1 = Math.min(a.rows, a.cols); const o1 = alloc(8 * s1);
    const o2 = matrixOut(a.cols, Math.min(a.rows, a.cols));
    check(wasm._rm_matrix_svd(c_a, o0.view, o1, o2.view));
    refresh();
    return [o0.matrix(), numbersOut(o1, s1, Float64Array), o2.matrix()];
}

/** A symmetric matrix's eigenvalues from the smallest up, each eigenvector a column. */
export function matrixEigen(a: Matrix): [Float64Array, Matrix] {
    begin();
    const c_a = matrixIn(a);
    const s0 = a.rows; const o0 = alloc(8 * s0);
    const o1 = matrixOut(a.rows, a.rows);
    check(wasm._rm_matrix_eigen(c_a, o0, o1.view));
    refresh();
    return [numbersOut(o0, s0, Float64Array), o1.matrix()];
}

/** The lower l with a = l l^T. Fails when a is not symmetric positive definite. */
export function matrixCholesky(a: Matrix): Matrix {
    begin();
    const c_a = matrixIn(a);
    const o0 = matrixOut(a.rows, a.cols);
    check(wasm._rm_matrix_cholesky(c_a, o0.view));
    refresh();
    return o0.matrix();
}

