export function axesPointsTo(axes: Axes, points: readonly Double3[] | Float64Array): Double3[] | Float64Array {
    begin();
    const c_axes = alloc(16); w_RantAxes(c_axes, axes);
    const n_points = countOf(points, 3); const c_points = listIn(points, n_points, 24, w_RantDouble3);
    const s0 = n_points; const o0 = alloc(24 * s0);
    wasm._rm_axes_points_to(c_axes, c_points, o0, n_points);
    refresh();
    return listOut(o0, s0, 24, r_RantDouble3, 3, points instanceof Float64Array);
}

