/** How far apart two shapes are by GJK, 0 when they touch, a solid filled and a mesh or polygon hollow. */
export function shapeGap(a: Shape, b: Shape): [number, Segment] {
    begin();
    const c_a = shapeIn(a);
    const c_b = shapeIn(b);
    const o0 = alloc(8);
    const o1 = alloc(48);
    check(wasm._rm_shape_gap(c_a, c_b, o0, o1));
    refresh();
    return [F64[(o0) >> 3], r_RantSegment(o1)];
}

