/** Through the points' mean, its normal facing the origin, where the sensor that saw them sits, or up
 * when the origin is no farther off the plane than the points are. Needs 3. */
export function pointsFitPlane(points: readonly Double3[] | Float64Array, options: FitOptions | null = null): Plane {
    begin();
    const n_points = countOf(points, 3); const c_points = listIn(points, n_points, 24, w_RantDouble3);
    const c_options = fitIn(options, n_points);
    const o0 = alloc(48);
    check(wasm._rm_points_fit_plane(c_points, n_points, c_options, o0));
    refresh();
    fitDone(options, c_options);
    return r_RantPlane(o0);
}

