export function pointsClusters(points: readonly Double3[] | Float64Array, distance: number, minPoints: number): [Uint32Array, number] {
    begin();
    const n_points = countOf(points, 3); const c_points = listIn(points, n_points, 24, w_RantDouble3);
    const s0 = n_points; const o0 = alloc(4 * s0);
    const o1 = alloc(4);
    check(wasm._rm_points_clusters(c_points, n_points, distance, minPoints, o0, o1));
    refresh();
    return [numbersOut(o0, s0, Uint32Array), U32[(o1) >> 2]];
}

export function pointsAlign(source: readonly Double3[] | Float64Array, target: readonly Double3[] | Float64Array, guess: Pose, options: AlignOptions | null = null): Pose {
    begin();
    const n_source = countOf(source, 3); const c_source = listIn(source, n_source, 24, w_RantDouble3);
    const n_target = countOf(target, 3); const c_target = listIn(target, n_target, 24, w_RantDouble3);
    const c_guess = alloc(56); w_RantPose(c_guess, guess);
    const c_options = alignIn(options, n_source, n_target);
    const o0 = alloc(56);
    check(wasm._rm_points_align(c_source, n_source, c_target, n_target, c_guess, c_options, o0));
    refresh();
    alignDone(options, c_options);
    return r_RantPose(o0);
}

/** A flat grid takes any z. */
export function gridCell(grid: Grid, point: Double3): Int3 {
    begin();
    const c_grid = gridIn(grid);
    const c_point = alloc(24); w_RantDouble3(c_point, point);
    const o0 = alloc(12);
    check(wasm._rm_grid_cell(c_grid, c_point, o0));
    refresh();
    return r_RantInt3(o0);
}

/** The middle of a cell in the parent frame, on the xy plane of a flat grid. */
export function gridCenter(grid: Grid, cell: Int3): Double3 {
    begin();
    const c_grid = gridIn(grid);
    const c_cell = alloc(12); w_RantInt3(c_cell, cell);
    const o0 = alloc(24);
    check(wasm._rm_grid_center(c_grid, c_cell, o0));
    refresh();
    return r_RantDouble3(o0);
}

/** A cell's number in the field of this name, a NUL ended string. */
export function gridReadValue(grid: Grid, field: string, cell: Int3): number {
    begin();
    const c_grid = gridIn(grid);
    const c_field = stringIn(field);
    const c_cell = alloc(12); w_RantInt3(c_cell, cell);
    const o0 = alloc(8);
    check(wasm._rm_grid_read_value(c_grid, c_field, c_cell, o0));
    refresh();
    return F64[(o0) >> 3];
}

/** Whole kinds are rounded and clamped, NaN to 0. */
export function gridWriteValue(grid: Grid, field: string, cell: Int3, value: number): void {
    begin();
    const c_grid = gridIn(grid);
    const c_field = stringIn(field);
    const c_cell = alloc(12); w_RantInt3(c_cell, cell);
    check(wasm._rm_grid_write_value(c_grid, c_field, c_cell, value));
    refresh();
    gridDone(grid, c_grid);
}

/** Meters from the Earth's center, x toward latitude 0 and longitude 0, z toward the north pole. Back,
 * longitude is in (-180, 180] and a pole's is 0. */
export function geoPointToEcef(point: GeoPoint): Double3 {
    begin();
    const c_point = alloc(24); w_RantGeoPoint(c_point, point);
    const ret = alloc(24);
    wasm._rm_geo_point_to_ecef(ret, c_point);
    refresh();
    return r_RantDouble3(ret);
}

export function geoPointFromEcef(ecef: Double3): GeoPoint {
    begin();
    const c_ecef = alloc(24); w_RantDouble3(c_ecef, ecef);
    const ret = alloc(24);
    wasm._rm_geo_point_from_ecef(ret, c_ecef);
    refresh();
    return r_RantGeoPoint(ret);
}

/** point in meters east, north and up of origin, the flat frame a robot maps a site in. */
export function geoPointToEnu(origin: GeoPoint, point: GeoPoint): Double3 {
    begin();
    const c_origin = alloc(24); w_RantGeoPoint(c_origin, origin);
    const c_point = alloc(24); w_RantGeoPoint(c_point, point);
    const ret = alloc(24);
    wasm._rm_geo_point_to_enu(ret, c_origin, c_point);
    refresh();
    return r_RantDouble3(ret);
}

export function geoPointFromEnu(origin: GeoPoint, enu: Double3): GeoPoint {
    begin();
    const c_origin = alloc(24); w_RantGeoPoint(c_origin, origin);
    const c_enu = alloc(24); w_RantDouble3(c_enu, enu);
    const ret = alloc(24);
    wasm._rm_geo_point_from_enu(ret, c_origin, c_enu);
    refresh();
    return r_RantGeoPoint(ret);
}

/** Non maximum suppression: keep gets 0 for each detection whose IoU with a kept one of the same label
 * and a higher score, or as high and earlier, is above iou. Labels left empty all match. */
export function detections2dSuppress(detections: readonly Detection2D[], iou: number): Uint8Array {
    begin();
    const c_detections = detectionsIn(detections, 56, w_RantDetection2DView, w_RantOrientedBox2D);
    const s0 = detections.length; const o0 = alloc(1 * s0);
    check(wasm._rm_detections2d_suppress(c_detections, detections.length, iou, o0));
    refresh();
    return numbersOut(o0, s0, Uint8Array);
}

export function detections3dSuppress(detections: readonly Detection3D[], iou: number): Uint8Array {
    begin();
    const c_detections = detectionsIn(detections, 96, w_RantDetection3DView, w_RantOrientedBox);
    const s0 = detections.length; const o0 = alloc(1 * s0);
    check(wasm._rm_detections3d_suppress(c_detections, detections.length, iou, o0));
    refresh();
    return numbersOut(o0, s0, Uint8Array);
}
